import static io.restassured.RestAssured.*;
import static org.hamcrest.Matchers.*;

@BeforeAll
static void setup() {
    baseURI = "https://reqres.in/api";
}

@Test
void getUserReturns200() {
    given()
    .when()
        .get("/users/1")
    .then()
        .statusCode(200)
        .body("data.first_name", equalTo("George"));
}
